#!/usr/bin/env python3
"""Build a portable showcase from the existing tour captures; never rerun the tour."""
from pathlib import Path
import base64
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "output/showcase/living-realms.html"

chapters = [
    dict(name="Your realm", title="A settlement you can shape.", image="world_built", text="Found a town, plan its streets, and watch villagers turn your designs into buildings. Living Realms connects construction, research, supplies, and a real Recruits garrison.", points=["Forge 1.20.1 · Villager Recruits add-on", "226 building entries in this test installation", "35 technologies · 5 research branches"], caption="The tour town partway through construction. Yellow outlines mark planned sites; some buildings are still unfinished."),
    dict(name="Found & govern", title="Your town, at a glance.", image="ui_overview", text="Place a Town Charter to found a settlement and receive Architect’s Plans. Press K to reopen City Manager: population, housing, happiness, food, treasury, taxes, and the next rank are all here.", points=["Six ranks: Camp → Hamlet → Village → Town → City → Capital", "Rank requirements include people, buildings, research, and emeralds", "A chronicle records what is happening in town"], caption="This is an accelerated development tour with seeded resources and rank, not a normal survival progression demonstration."),
    dict(name="Choose buildings", title="Give every district a purpose.", image="ui_build_townhall", text="Browse civic buildings, homes, farms, mines, smithies, libraries, barracks, stables, taverns, walls, and more. A 3D preview shows the building before you place it.", points=["Five styles: plains, taiga, snowy, desert, and savanna", "Building levels expand procedural designs; template houses receive renovations", "Vanilla village templates are included; CTOV and Towns & Towers are optional"], caption="The catalog shows 226 entries in the tested setup. Counts vary with installed mods. Optional mod houses have not been verified in game."),
    dict(name="Plan in the world", title="Place it exactly where it belongs.", image="world_placing", text="Architect’s Plans put a translucent building preview into the world. Move it into position, rotate it, adjust the height, and confirm the site.", points=["Right-click: place the plan", "Scroll: rotate · Shift + scroll: raise or lower", "Shift + right-click: cancel placement"], caption="An actual library placement preview, captured in the tour world."),
    dict(name="Watch it grow", title="From ghost plans to a town.", image="world_planned", text="Builders walk to each site and place blocks from the shared stockpile. Move through three captures of the same view to see construction progress.", points=["Projects queue each building and show progress", "Missing materials pause a site and identify what is needed", "These captures show progress, not a fully finished town"], caption="Stage 1 of 3 · Plans laid out.", stages=["world_planned", "world_building", "world_built"]),
    dict(name="Map & roads", title="Connect the pieces.", image="ui_map_late", text="Pan and zoom around the town map, select buildings, and lay roads from point to point. Choose a surface and width to fit the district.", points=["Color-coded building categories", "Path, gravel, cobblestone, stone brick, and timber road choices", "The town boundary and alarm state are visible"], caption="The late-tour map shows the road, building plots, and active alarm."),
    dict(name="Stockpile", title="One supply pool for the whole town.", image="ui_storage", text="Deposit supplies through City Manager or a Delivery Barrel. Builders, smiths, and soldiers draw from town storage, wherever they are working.", points=["Search supplies and withdraw stacks", "Construction waits when a required block runs out", "Food reserves support the population and garrison"], caption="The test deliberately seeds large material reserves. The displayed stockpile is not a normal starting inventory."),
    dict(name="Research", title="Build knowledge before an empire.", image="ui_research", text="Libraries generate research points. Spend points and required items on technologies that unlock buildings, settlement ranks, smithing materials, and military units.", points=["Economy · Construction · Scholarship · Smithing · Military", "35 technologies with prerequisite paths", "Pan around the tree and inspect each unlock"], caption="The captured tree shows Steelmaking in progress and Plate Armour’s prerequisite."),
    dict(name="Blacksmith", title="Order equipment for your people.", image="ui_forge", text="Choose a piece or a full armour set, a researched material, and a quantity. Smithies are designed to consume supplies and return finished equipment to the stockpile.", points=["Leather, chainmail, iron, gold, diamond, and netherite", "Optional Epic Knights patterns include steel and plate sets", "Weapons and shields are available alongside armour"], caption="This early capture shows the smithy requirement still locked. Later tour logs record queued orders, but order completion was not verified."),
    dict(name="Recruit & equip", title="Build the army your town needs.", image="ui_kits", text="Train footmen, shieldbearers, bowmen, crossbowmen, and horsemen. Set armour and weapon kits for each role, then equip new soldiers from the town’s supplies.", points=["A barracks and available townsfolk are needed for recruitment", "Research gates advanced unit types", "Auto-equip new soldiers or equip the garrison together"], caption="The kits screen shows equipment choices for all five roles. Five soldiers were present in the final tour log."),
    dict(name="Command", title="A garrison with a job to do.", image="ui_garrison", text="Set the town’s military stance, inspect individual soldiers, and respond when enemies approach. These are actual Villager Recruits soldiers.", points=["Patrol · Garrison · Muster · Follow · At ease", "Watchtowers raise an alarm for nearby enemies", "Town supplies feed and resupply the garrison"], caption="The captured garrison has two footmen, two bowmen, and one shieldbearer, with Muster active during an alarm."),
    dict(name="Living villages", title="The world grows around you.", image="world_ai_town", text="Generated villages become AI settlements. They plan new buildings, grow their economy, and raise their own garrisons; the simulation catches up when their chunks load again.", points=["The tour recorded two active AI towns", "Both had five soldiers in the final log", "New building sites appear alongside the original village"], caption="An actual AI village from the tour, with existing homes, fields, roads, and a new planned building."),
]

images = {}
for chapter in chapters:
    for name in [chapter["image"], *chapter.get("stages", [])]:
        if name not in images:
            path = ROOT / "run/screenshots" / f"livingrealms_{name}.png"
            images[name] = "data:image/png;base64," + base64.b64encode(path.read_bytes()).decode()

template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Living Realms — a little tour</title>
<style>
:root{color-scheme:dark;--bg:#101812;--panel:#18221b;--line:#334337;--gold:#e5bd73;--ink:#f5f1e7;--muted:#b8c3b7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,sans-serif}button,a,input{touch-action:manipulation}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:4px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 4vw;border-bottom:1px solid var(--line)}.brand{font-family:Georgia,serif;font-size:27px;letter-spacing:.02em}.brand span{color:var(--gold)}.eyebrow{color:var(--gold);font-size:12px;text-transform:uppercase;letter-spacing:.18em}.tag{font-size:13px;color:var(--muted)}main{max-width:1680px;margin:auto;padding:28px 4vw 48px}.intro{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px}h1{font:clamp(30px,3.2vw,48px)/1.12 Georgia,serif;margin:8px 0 0}.intro p{max-width:390px;color:var(--muted);font-size:14px;margin:0}.layout{display:grid;grid-template-columns:200px minmax(0,1fr);gap:26px}nav{display:flex;flex-direction:column;gap:4px}nav button{display:flex;gap:12px;align-items:center;text-align:left;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--muted);padding:11px 12px;font-size:14px}nav button small{font-size:10px;font-variant-numeric:tabular-nums;opacity:.65}nav button[aria-current="step"]{color:var(--ink);background:#26382b;border-color:#425745}nav button[aria-current="step"] small{color:var(--gold);opacity:1}.screen{background:#080d09;border:1px solid var(--line);border-radius:10px;overflow:hidden}.imagebutton{display:block;border:0;padding:0;background:transparent;width:100%;cursor:zoom-in}.imagebutton img{display:block;width:100%;aspect-ratio:1708/960;object-fit:contain}.caption{padding:12px 17px;margin:0;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}.details{display:grid;grid-template-columns:1.1fr 1fr;gap:32px;margin-top:24px}h2{font:30px/1.15 Georgia,serif;margin:0 0 12px}.description{margin:0;color:var(--muted);font-size:15px}.details ul{margin:0;padding:0;list-style:none;font-size:14px}.details li{padding:10px 0 10px 20px;border-bottom:1px solid var(--line);position:relative}.details li:before{content:'◆';position:absolute;left:0;top:12px;color:var(--gold);font-size:8px}.controls{display:flex;align-items:center;gap:12px;margin-top:24px}.controls button,.stage button{border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--ink);padding:9px 15px}.controls button:last-child{background:var(--gold);color:#201c12;border-color:var(--gold)}.controls button:disabled{opacity:.35;cursor:default}#counter{margin-left:auto;color:var(--muted);font-size:12px}.stage{padding:14px 18px;background:#1e2c22;border-top:1px solid var(--line);display:flex;gap:12px;align-items:center;flex-wrap:wrap}.stage[hidden]{display:none}.stage label{font-size:13px;color:var(--gold)}.stage input{flex:1;min-width:120px;accent-color:var(--gold)}.stage output{font-size:13px;min-width:135px}.foot{margin-top:40px;padding-top:24px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:32px;font-size:13px;color:var(--muted)}.foot h3{color:var(--ink);font-size:14px;margin:0 0 8px}.foot p{margin:0}.foot a{color:var(--gold)}dialog{max-width:96vw;width:1600px;padding:14px;border:1px solid var(--line);border-radius:10px;background:#101812;color:var(--ink)}dialog::backdrop{background:#000d}dialog img{width:100%;display:block;margin-top:12px}dialog button{background:var(--gold);border:0;border-radius:5px;padding:8px 16px;color:#201c12}dialog .top{display:flex;align-items:center;justify-content:space-between;gap:14px}.hint{font-size:12px;color:var(--muted)}@media(max-width:900px){.layout{grid-template-columns:1fr}nav{flex-direction:row;overflow:auto;padding-bottom:8px}nav button{white-space:nowrap}.intro{display:block}.intro p{margin-top:14px;max-width:none}.details{gap:22px}.tag{display:none}}@media(max-width:600px){header{padding:16px 5vw}main{padding:22px 5vw}.brand{font-size:23px}.details,.foot{grid-template-columns:1fr}.details h2{font-size:27px}.details{gap:12px}.controls{flex-wrap:wrap}.hint{display:none}h1{font-size:34px}.caption{font-size:12px}.foot{gap:20px}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s}}@media print{nav,.controls,.hint{display:none}.layout{display:block}body{background:white;color:black}.description,.caption,.foot{color:#333}}
</style></head><body>
<header><div class="brand">Living <span>Realms</span></div><div class="tag">Minecraft 1.20.1 · Feature showcase · v0.1.0</div></header>
<main><div class="intro"><div><div class="eyebrow">A little tour of your world</div><h1>Build a town.<br>Give it a life.</h1></div><p>Twelve stops through the real game captures. Explore at your own pace, or use the arrow keys to move through the tour.</p></div>
<div class="layout"><nav id="chapters" aria-label="Showcase chapters"></nav><section aria-label="Current feature">
<div class="screen"><button class="imagebutton" id="enlarge" aria-label="Enlarge game screenshot"><img id="capture" alt=""></button><div class="stage" id="stage" hidden><label for="progress">Construction</label><input id="progress" type="range" min="0" max="2" value="0" step="1"><output for="progress" id="stageLabel"></output></div><p class="caption" id="caption"></p></div>
<div class="details" aria-live="polite"><div><h2 id="heading"></h2><p class="description" id="description"></p></div><ul id="points"></ul></div>
<div class="controls"><button id="prev">← Previous</button><span class="hint">Click the screenshot to enlarge</span><span id="counter"></span><button id="next">Next stop →</button></div>
</section></div>
<footer class="foot"><div><h3>What these captures demonstrate</h3><p>Actual screenshots from the October 26 development tour: construction progress, City Manager, placement previews, research, five garrison soldiers, and AI village growth. The test uses seeded resources and accelerated setup. Some sites were still waiting for supplies when it ended.</p></div><div><h3>Still to verify in game</h3><p>Completed smithy orders, optional CTOV / Towns &amp; Towers houses, and compatibility with Crowns &amp; Dragonfire. This tour does not establish those results. Start playing by crafting a Town Charter, then use <strong>K</strong> for City Manager. Requires Forge 47+ and Villager Recruits 1.15+.</p></div></footer>
</main><dialog id="zoom"><div class="top"><span id="zoomTitle"></span><button id="closeZoom">Close ✕</button></div><img id="zoomImage" alt=""></dialog>
<script>
const chapters=__CHAPTERS__, images=__IMAGES__;
const $=id=>document.getElementById(id);let current=0;
const stages=['Plans laid out','Builders at work','Later progress'];
chapters.forEach((chapter,index)=>{const button=document.createElement('button');button.innerHTML='<small>'+String(index+1).padStart(2,'0')+'</small><span></span>';button.querySelector('span').textContent=chapter.name;button.addEventListener('click',()=>show(index));$('chapters').append(button)});
function show(index){current=Math.max(0,Math.min(chapters.length-1,index));const c=chapters[current];$('capture').src=images[c.image];$('capture').alt=c.title+' — '+c.caption;$('heading').textContent=c.title;$('description').textContent=c.text;$('caption').textContent=c.caption;$('points').replaceChildren(...c.points.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));[...$('chapters').children].forEach((b,i)=>{if(i===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});$('stage').hidden=!c.stages;$('progress').value=0;$('stageLabel').textContent=stages[0];$('prev').disabled=current===0;$('next').disabled=current===chapters.length-1;$('counter').textContent=String(current+1).padStart(2,'0')+' / '+chapters.length;history.replaceState(null,'','#'+(current+1));}
$('progress').addEventListener('input',()=>{const n=Number($('progress').value);$('capture').src=images[chapters[current].stages[n]];$('capture').alt='Construction stage '+(n+1)+': '+stages[n];$('stageLabel').textContent=stages[n];$('caption').textContent='Stage '+(n+1)+' of 3 · '+stages[n]+'. Same viewpoint across the development tour; some sites remain unfinished.';});
$('prev').addEventListener('click',()=>show(current-1));$('next').addEventListener('click',()=>show(current+1));
document.addEventListener('keydown',e=>{if($('zoom').open||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}});
$('enlarge').addEventListener('click',()=>{$('zoomImage').src=$('capture').src;$('zoomImage').alt=$('capture').alt;$('zoomTitle').textContent=chapters[current].name;$('zoom').showModal()});$('closeZoom').addEventListener('click',()=>$('zoom').close());
const initial=Number(location.hash.slice(1));show(Number.isInteger(initial)&&initial>0?initial-1:0);
</script></body></html>'''

OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(template.replace("__CHAPTERS__", json.dumps(chapters)).replace("__IMAGES__", json.dumps(images)))
print(f"Built {OUT} ({OUT.stat().st_size:,} bytes; {len(chapters)} chapters; {len(images)} original captures)")
